async function openStudioObs(reconnecting){if(!studioObsCredentials||state.view!=='studio')return;clearTimeout(studioObsReconnectTimer);studioObsClient?.disconnect();const status=document.querySelector('#obsStatus');if(status)status.textContent=reconnecting?`OBS reconnect · спроба ${studioObsReconnectAttempt}…`:'Підключення до локального OBS…';try{const client=new ObsWebSocketClient({...studioObsCredentials,onDisconnect:scheduleStudioObsReconnect});studioObsClient=client;await client.connect();const caps=await client.capabilities();if(studioObsClient!==client)return;studioObsReconnectAttempt=0;applyStudioObsCapabilities(caps,'OBS')}catch(error){if(status)status.textContent=`OBS: ${obsErrorText(error)}`;scheduleStudioObsReconnect()}}
