function loadStudioScene(scenes){const id=document.querySelector('#savedScene').value,scene=scenes.find(x=>x.id===id);if(!scene)return;document.querySelector('#sceneName').value=scene.name;document.querySelector('#overlayTitle').value=scene.overlayTitle;document.querySelector('#overlayStyle').value=scene.overlayStyle;if(STUDIO_PROFILES[scene.profileId])document.querySelector('#studioProfile').value=scene.profileId;const gain=document.querySelector('#studioMicGain'),mute=document.querySelector('#studioMicMute');if(gain)gain.value=String(Math.max(0,Math.min(150,Number(scene.micGain??100))));if(mute){mute.dataset.muted=scene.micMuted?'1':'0';mute.textContent=scene.micMuted?'Unmute':'Mute'}localStorage.setItem('sylora_studio_profile',document.querySelector('#studioProfile').value);persistStudioRecovery();configureStudioCanvas();updateStudioAudioGain();if(studioSourceStream)composeStudioFrame();else drawStudioPlaceholder()}
async function saveStudioScene(){const id=document.querySelector('#savedScene').value,name=document.querySelector('#sceneName').value,preset=studioPresetState();try{await api(id?`/api/studio/scenes/${id}`:'/api/studio/scenes',{method:id?'PATCH':'POST',body:JSON.stringify({name,...preset})});persistStudioRecovery();toast(id?'Scene оновлено':'Scene збережено');renderStudio()}catch(e){toast(e.message)}}
